@pytest.mark.parametrize("version", [v975, v1001])
def test_primitive_shapes_is_packet_328(version):
    assert version.PACKETS[328] is version.PrimitiveShapesPacket


@pytest.mark.parametrize(
    ("version", "packet_type"),
    [
        pytest.param(v844, v844.ServerScriptDebugDrawerPacket, id="v844-server-script-debug-drawer"),
        pytest.param(v859, v859.DebugDrawerPacket, id="v859-debug-drawer"),
        pytest.param(v924, v924.DebugDrawerPacket, id="v924-debug-drawer"),
        pytest.param(v944, v944.DebugDrawerPacket, id="v944-debug-drawer"),
        pytest.param(v975, v975.PrimitiveShapesPacket, id="v975-primitive-shapes"),
    ],
)
def test_id_328_changes_owner_at_859_and_again_at_975(version, packet_type):
    assert version.PACKETS[328] is packet_type


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_primitive_shapes_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_primitive_shapes_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("dimension_id", [pytest.param(0, id="dimension-0"), pytest.param(None, id="no-dimension")])
def test_the_898_shape_round_trips_its_optional_dimension(dimension_id):
    packet = v898.DebugDrawerPacket(shapes=[v898.PrimitiveShapeDataPayload(network_id=1, dimension_id=dimension_id)])
    assert v898.DebugDrawerPacket.from_bytes(bytes(packet)) == packet


def test_dimension_id_gains_its_presence_byte_at_898():
    newer = v898.DebugDrawerPacket(shapes=[v898.PrimitiveShapeDataPayload(network_id=1, dimension_id=0)])
    older = v859.DebugDrawerPacket(shapes=[v859.PrimitiveShapeDataPayload(network_id=1, dimension_id=0)])
    assert len(bytes(newer)) == len(bytes(older)) + 1
